task large_product(a: seq, b: seq, n: int) returns (r: seq)
  requires n >= 0
  requires n <= len(a)
  requires n <= len(b)
  ensures len(r) == n
  ensures forall i in [0, n) . r[i] == max_product(i)
  ensures forall i in [0, n) . j in [i+1, n) . r[i] >= r[j]
  ensures forall i in [0, n) . exists j in [0, len(a)) . exists k in [0, len(b)) . r[i] == a[j] * b[k]
{
  var products: seq := [];
  var i: int := 0;
  var j: int := 0;
  while i < n and j < len(a) and j < len(b)
    invariant i <= n
    invariant j >= 0
    invariant len(products) == i
    invariant forall k in [0, i) . products[k] == max_product(k)
    invariant forall k in [0, i) . m in [k+1, i) . products[k] >= products[m]
    decreases n - i + j
  {
    var p1: int := a[i] * b[j];
    var p2: int := a[i] * b[j + 1];
    if p1 > p2 {
      products := products + [p1];
      i := i + 1;
    } else {
      j := j + 1;
    }
  }
  r := products;
}
